<?php $page_title='Community Events'; require_once 'includes/header.php'; require_login(); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']);$desc=trim($_POST['description']);$loc=trim($_POST['location']);$dt=$_POST['starts_at'];if($title&&$dt){$pdo->prepare('INSERT INTO community_events(title,description,location,starts_at,created_by) VALUES(?,?,?,?,?)')->execute([$title,$desc,$loc,$dt,user()['id']]);flash('success','Event created.');}redirect('events.php');}$events=$pdo->query("SELECT e.*,u.name creator FROM community_events e LEFT JOIN users u ON u.id=e.created_by WHERE e.starts_at>=NOW() ORDER BY e.starts_at ASC")->fetchAll(); ?>
<section class="page-hero"><span class="kicker">COMMUNITY / EVENTS</span><h1>Meet, volunteer and share.</h1><p>Coordinate food drives, volunteer days and community meetups.</p></section><section class="admin-form-card"><h2>Create an event</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Event title<input name="title" required></label><label>Location<input name="location"></label><label>Date & time<input type="datetime-local" name="starts_at" required></label><label>Description<textarea name="description"></textarea></label><button class="btn primary">Create event</button></form></section><div class="event-public-grid"><?php foreach($events as $ev):?><article class="event-card"><div class="event-date"><?=date('d',strtotime($ev['starts_at']))?><small><?=date('M',strtotime($ev['starts_at']))?></small></div><div><span class="kicker">FIBIN EVENT</span><h3><?=e($ev['title'])?></h3><p><?=e($ev['description']?:'Community event')?></p><small>📍 <?=e($ev['location']?:'Online / local community')?> · by <?=e($ev['creator']?:'FIBIN')?></small></div></article><?php endforeach;if(!$events):?><div class="empty-state full">No upcoming events.</div><?php endif;?></div>
<?php require_once 'includes/footer.php'; ?>
